package local.tvmorph.playercheck;
import android.app.*;import android.content.*;import android.os.*;import java.lang.reflect.*;
/** Real decoder/surface proof; no screenshot capture. */
public final class VideoStartInstrumentation extends Instrumentation {
 private Activity player;
 private Object field(Object owner,String name)throws Exception{for(Class<?> c=owner.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(owner);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
 private Object invoke(Object owner,String name)throws Exception{for(Class<?> c=owner.getClass();c!=null;c=c.getSuperclass())try{Method m=c.getDeclaredMethod(name);m.setAccessible(true);return m.invoke(owner);}catch(NoSuchMethodException ignored){}throw new NoSuchMethodException(name);}
 private void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 private void nativeParental()throws Exception{Context context=getTargetContext();android.content.SharedPreferences preferences=context.getSharedPreferences("morph-iptv-parental",0);String previous=preferences.getString("scopes","{}");try{Class<?> storeClass=Class.forName("local.tvmorph.tv.IptvStore");Method get=storeClass.getDeclaredMethod("get",Context.class);get.setAccessible(true);Object store=get.invoke(null,context);Method summary=storeClass.getDeclaredMethod("summary");summary.setAccessible(true);org.json.JSONObject info=(org.json.JSONObject)summary.invoke(store);String scope=info.optString("profileId","default")+"@default";org.json.JSONObject rules=new org.json.JSONObject().put("live:999",new org.json.JSONObject().put("locked",true)).put("live:998",new org.json.JSONObject().put("hidden",true)).put("live:997",new org.json.JSONObject().put("until",System.currentTimeMillis()+60000));preferences.edit().putString("scopes",new org.json.JSONObject().put(scope,new org.json.JSONObject().put("enabled",true).put("rules",rules)).toString()).commit();Class<?> policy=Class.forName("local.tvmorph.tv.IptvParentalStore");Method restricted=policy.getDeclaredMethod("restricted",Context.class,org.json.JSONObject.class),deadline=policy.getDeclaredMethod("deadline",Context.class,org.json.JSONObject.class);restricted.setAccessible(true);deadline.setAccessible(true);org.json.JSONObject locked=new org.json.JSONObject().put("kind","live").put("id","999");check(Boolean.TRUE.equals(restricted.invoke(null,context,locked)),"Native remote gate sees locked IDs");check(Boolean.TRUE.equals(restricted.invoke(null,context,new org.json.JSONObject().put("kind","live").put("id","998"))),"Native remote gate sees hidden IDs");check(((Long)deadline.invoke(null,context,new org.json.JSONObject().put("kind","live").put("id","997")))>System.currentTimeMillis(),"Native timer recovered from stored content rules");Method play=Class.forName("local.tvmorph.tv.IptvActivity").getDeclaredMethod("play",Context.class,org.json.JSONObject.class);play.setAccessible(true);boolean denied=false;try{play.invoke(null,context,locked);}catch(InvocationTargetException error){denied=error.getCause() instanceof java.io.IOException;}check(denied,"Direct remote/native playback cannot bypass the content lock");}finally{preferences.edit().putString("scopes",previous).commit();}}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{nativeParental();getTargetContext().getSharedPreferences("tvmorph-ui",0).edit().putBoolean("systemLivePlayer",false).putString("language","en").commit();Intent intent=new Intent().setClassName("local.tvmorph.tv","local.tvmorph.tv.PlayerActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("url","http://10.0.2.2:8771/fhd.mp4").putExtra("name","Local FHD decoder QA").putExtra("itemKind","live").putExtra("itemId","991").putExtra("live",true);player=startActivitySync(intent);Object video=field(player,"video");long until=SystemClock.uptimeMillis()+25000;boolean[] rendered={false};while(SystemClock.uptimeMillis()<until){runOnMainSync(()->{try{rendered[0]=Boolean.TRUE.equals(invoke(video,"hasVideoFrame"));}catch(Exception e){throw new RuntimeException(e);}});if(rendered[0])break;Thread.sleep(100);}check(rendered[0],"A real FHD frame must reach the video surface");check(Boolean.TRUE.equals(invoke(video,"buffered")),"Live starts with Media3 by default");check(((Integer)field(video,"width"))>=1920,"Actual decoded FHD width");runOnMainSync(()->player.finish());waitForIdleSync();Intent limited=new Intent(intent).putExtra("parentalDeadline",System.currentTimeMillis()+3000);player=startActivitySync(limited);Thread.sleep(4800);check(player.isFinishing()||player.isDestroyed(),"Saved parental deadline must stop the native player");result.putString("result","PASS actual 1920px video frame, Media3 live default and enforced parental playback deadline; no screenshot taken");finish(-1,result);}catch(Throwable e){if(player!=null)runOnMainSync(()->player.finish());result.putString("error",e.toString());finish(0,result);}}
}
